import java.util.Scanner;

public class e1542easy {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int total = input.nextInt();
        int modulus = input.nextInt();
        performCalculation(total, modulus);
        input.close();
    }

    public static void performCalculation(int total, int modulus) {
        java.util.List<long[]> inversionList = new java.util.ArrayList<>();
        inversionList.add(new long[]{1});
        for (int i = 1; i < total; i++) {
            long[] previous = inversionList.get(i - 1);
            long[] current = new long[i * (i + 1) / 2 + 1];
            for (int j = 0; j < current.length; j++) {
                long sum = 0;
                for (int k = Math.min(j, i); k >= 0; k--) {
                    if (j - k < previous.length) {
                        sum += previous[j - k];
                        sum %= modulus;
                    }
                }
                current[j] = sum;
            }
            inversionList.add(current);
        }

        long[] permutationCounts = new long[total];
        permutationCounts[0] = 0;
        for (int i = 1; i < total; i++) {
            long count = (permutationCounts[i - 1] * (i + 1)) % modulus;
            long[] invArr = inversionList.get(i - 1);
            for (int j = 0; j < invArr.length; j++) {
                for (int k = j + 2; k < invArr.length; k++) {
                    long mVal = Math.min(k - j, i + 1);
                    long add = ((invArr[j] * invArr[k]) % modulus) * ((mVal - 1) * (2 * i - (mVal - 2)) / 2);
                    count = (count + add) % modulus;
                }
            }
            permutationCounts[i] = count;
        }
        System.out.println(permutationCounts[total - 1]);
    }
}
